    {"id": "VERBESSERN:spielregeln","schwach": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären. Das finde ich einfach gut.","optionen": [{"text": "Dann kennen beide Teams dieselben Regeln.","ok": true,"info": "Dieser Grund erklärt, warum der Vorschlag sinnvoll ist.","warum": [{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": true},{"text": "Beim Turnier spielen mehrere Teams.","ok": false},{"text": "Die Spielregeln stehen auf einem Plakat.","ok": false}]},{"text": "Beim Turnier spielen mehrere Teams.","ok": false,"info": "Das passt zum Thema, erklärt aber nicht das Warum."},{"text": "Die Spielregeln stehen auf einem Plakat.","ok": false,"info": "Das beschreibt nur ein Detail und ist noch kein Grund."}]},
    {"id": "VERBESSERN:radstaender","schwach": "Wir sollten Fahrräder an festen Plätzen abstellen. Das finde ich einfach gut.","optionen": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true,"info": "Dieser Grund erklärt, warum der Vorschlag sinnvoll ist.","warum": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true},{"text": "Die Fahrradständer stehen neben der Schule.","ok": false},{"text": "Amins Fahrrad ist rot.","ok": false}]},{"text": "Die Fahrradständer stehen neben der Schule.","ok": false,"info": "Das passt zum Thema, erklärt aber nicht das Warum."},{"text": "Amins Fahrrad ist rot.","ok": false,"info": "Das beschreibt nur ein Detail und ist noch kein Grund."}]},
    {"id": "VERBESSERN:tauschregal","schwach": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen. Das finde ich einfach gut.","optionen": [{"text": "Dann müssen wir weniger neu kaufen.","ok": true,"info": "Dieser Grund erklärt, warum der Vorschlag sinnvoll ist.","warum": [{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": true},{"text": "Im Tauschregal liegen Schulsachen.","ok": false},{"text": "Das Regal hat vier Fächer.","ok": false}]},{"text": "Im Tauschregal liegen Schulsachen.","ok": false,"info": "Das passt zum Thema, erklärt aber nicht das Warum."},{"text": "Das Regal hat vier Fächer.","ok": false,"info": "Das beschreibt nur ein Detail und ist noch kein Grund."}]},
    {"id": "VERBESSERN:lernpause","schwach": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen. Das finde ich einfach gut.","optionen": [{"text": "Nach etwas Bewegung fällt es uns leichter, wieder aufzupassen.","ok": true,"info": "Dieser Grund erklärt, warum der Vorschlag sinnvoll ist.","warum": [{"text": "Nach etwas Bewegung fällt es uns leichter, wieder aufzupassen.","ok": true},{"text": "Die Bewegungspause liegt zwischen zwei Arbeitsphasen.","ok": false},{"text": "Die Pausenkarte hängt an der Tafel.","ok": false}]},{"text": "Die Bewegungspause liegt zwischen zwei Arbeitsphasen.","ok": false,"info": "Das passt zum Thema, erklärt aber nicht das Warum."},{"text": "Die Pausenkarte hängt an der Tafel.","ok": false,"info": "Das beschreibt nur ein Detail und ist noch kein Grund."}]}
