    {"id": "GEGEN_BELEGT:klassenfahrt","argument": "Wir sollten auf der Klassenfahrt Aufgaben im Team lösen, weil wir dabei auch Kinder außerhalb unseres Freundeskreises kennenlernen. Bei der Wegsuche arbeiteten Mila und Ben zum ersten Mal zusammen und lernten sich besser kennen.","optionen": [{"text": "Bei einem Wettbewerb können schwächere Kinder ausgeschlossen werden.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Bei Teamaufgaben lernen wir auch andere Kinder aus der Klasse besser kennen.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die Klassenfahrt dauert mehrere Tage.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:schulhof","argument": "Wir sollten Spielgeräte in der Pause ausleihen können, weil auch Kinder ohne eigenes Gerät etwas ausprobieren können. Ivo hatte kein Springseil dabei und konnte sich eines ausleihen.","optionen": [{"text": "Manche Geräte werden vielleicht nicht wieder zurückgebracht.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Die Ausleihe ermöglicht Spiele auch ohne eigene Geräte.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die Spielgeräte liegen in einer Kiste.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:sport","argument": "Wir sollten im Sport verschiedene Spiele ausprobieren, weil dann mehr Kinder ein Spiel finden, das zu ihren Stärken passt. Sam war beim Fangen langsam, traf beim Zielwerfen aber fast jedes Mal.","optionen": [{"text": "Bei ständig neuen Spielen geht viel Zeit fürs Erklären verloren.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Verschiedene Spiele geben Kindern mit unterschiedlichen Stärken eine Chance.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die Sportspiele haben verschiedene Regeln.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:ags","argument": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten, weil wir vor der Wahl die Tätigkeit selbst ausprobieren. Nach dem Bauen eines Modells wusste Deniz, dass die Werk-AG passt.","optionen": [{"text": "Für mehrere Schnupperstunden fehlt uns die freie Zeit.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Beim Schnuppern können wir die Tätigkeit vor der Wahl testen.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die AGs finden nach dem Unterricht statt.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:handys","argument": "Wir sollten Handys während der Gruppenarbeit weglegen, weil keine Nachricht mitten im Gespräch unsere Aufmerksamkeit ablenkt. Ohne Nachrichtenton hörte Jona den Vorschlag seiner Partnerin zu Ende.","optionen": [{"text": "Für manche Aufgaben brauchen wir das Handy zum Nachschlagen.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Ohne Nachrichten werden wir im Gespräch seltener abgelenkt.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die Handys liegen während der Arbeit in Taschen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:haustiere","argument": "Wir sollten vor dem Tierkauf einen Pflegeplan machen, weil wir vorher klären, wer jeden Tag welche Aufgabe übernimmt. Im Plan steht, wer das Meerschweinchen auch am Sonntag füttert.","optionen": [{"text": "In den Ferien ist vielleicht die ganze Familie unterwegs.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Im Pflegeplan steht, wer das Tier jeden Tag füttert und versorgt.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Auf dem Pflegeplan stehen Namen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:freizeit","argument": "Wir sollten einen Nachmittag ohne feste Termine lassen, weil wir selbst entscheiden können, was wir beginnen möchten. Ayla baute an ihrem freien Nachmittag aus Kartons ein eigenes Spiel.","optionen": [{"text": "Der freie Nachmittag könnte mit einem Sportkurs zusammenfallen.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "In freier Zeit können wir selbst ein eigenes Vorhaben beginnen.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Der Nachmittag hat keinen festen Kurs.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:fahrrad","argument": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen, weil wir defekte Bremsen noch vor der Abfahrt entdecken. Beim Bremsentest merkte Paul, dass seine hintere Bremse nicht greift.","optionen": [{"text": "Nicht alle Kinder können eine kaputte Bremse reparieren.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Beim Test fallen kaputte Bremsen schon vor der Abfahrt auf.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die Räder stehen vor dem Ausflug auf dem Hof.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:schulweg","argument": "Wir sollten auf dem Schulweg sichere Stellen zum Überqueren wählen, weil wir dort herankommende Autos rechtzeitig sehen können. An der freien Kreuzung konnte Eda beide Fahrtrichtungen gut sehen.","optionen": [{"text": "Der Weg zur übersichtlichen Stelle ist etwas länger.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "An übersichtlichen Stellen sehen wir herankommende Autos rechtzeitig.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Auf dem Schulweg gibt es mehrere Straßen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:umwelt","argument": "Wir sollten in leeren Klassenräumen das Licht ausschalten, weil wir dann keinen Strom für einen leeren Raum verbrauchen. Während die Klasse beim Sport war, blieben die Lampen im Raum aus.","optionen": [{"text": "Das letzte Kind vergisst das Ausschalten vielleicht im Alltag.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Ausgeschaltete Lampen verbrauchen keinen Strom.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "An der Decke hängen mehrere Lampen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:muell","argument": "Wir sollten Papier getrennt von Essensresten sammeln, weil das Papier ohne Essensreste sauber bleibt und wiederverwendet werden kann. Die alten Arbeitsblätter blieben ohne die Bananenschalen sauber.","optionen": [{"text": "Manche Kinder wissen nicht, welcher Abfall wohin gehört.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Sauberes Altpapier kann zu neuem Papier verarbeitet werden.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Für Papier gibt es einen eigenen Eimer.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:ausflug","argument": "Wir sollten ein Ausflugsziel wählen, das wir mit dem Bus erreichen, weil niemand für die Anfahrt ein eigenes Auto braucht. Auch Nuri konnte mitfahren, obwohl seine Familie kein Auto hat.","optionen": [{"text": "Die Fahrkarten könnten für manche Familien zu teuer sein.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Im Bus kann man auch ohne eigenes Auto zum Ziel mitkommen.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Der Bus hält vor unserer Schule.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:klassenfest","argument": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten, weil jedes Kind eine Aufgabe finden kann, die es gern übernimmt. Luz wollte nicht auftreten und gestaltete stattdessen die Einladung.","optionen": [{"text": "Beliebte Aufgaben werden vielleicht von zu vielen Kindern gewählt.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Bei verschiedenen Aufgaben kann auch mithelfen, wer nicht auftreten möchte.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Auf dem Fest gibt es mehrere Aufgaben.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:gruppenarbeit","argument": "Wir sollten in Gruppen klare Aufgaben absprechen, weil jeder weiß, welchen Teil der Aufgabe er übernimmt. Lara suchte Bilder, während Cem den Text schrieb; kein Teil fehlte.","optionen": [{"text": "Eine Aufgabe kann für ein Kind zu schwer sein.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Durch Absprachen kennt jeder seinen eigenen Teil der Aufgabe.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "In der Gruppe sitzen mehrere Kinder.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:bibliothek","argument": "Wir sollten die Regale unserer Klassenbibliothek nach Themen beschriften, weil wir am Schild sofort das Thema eines Regals erkennen. Unter dem Schild Tiergeschichten fand Kim sofort ein passendes Buch.","optionen": [{"text": "Bei zu vielen kleinen Buchgruppen wird die Suche unübersichtlich.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Die Schilder zeigen sofort, welches Thema ein Regal enthält.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die Bücher stehen in mehreren Regalen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:schulessen","argument": "Wir sollten beim Schulessen kleine erste Portionen wählen, weil wir bei Bedarf nachnehmen können und weniger Essen wegwerfen. Sibel nahm wenig Reis, aß alles und holte bei Bedarf noch etwas.","optionen": [{"text": "Langes Anstehen zum Nachholen könnte die Essenszeit verkürzen.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Wer erst wenig nimmt und bei Hunger nachholt, lässt weniger Essen übrig.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "An der Ausgabe stehen Teller bereit.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:trinken","argument": "Wir sollten Wasserflaschen im Klassenraum auffüllen können, weil wir dann auch mit einer leeren Flasche genug zu trinken bekommen. Nach dem Sport füllte Ravi seine leere Flasche auf und trank daraus.","optionen": [{"text": "Am Wasserhahn könnte mitten im Unterricht eine Schlange entstehen.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Wir können unsere leere Flasche nachfüllen und müssen nicht durstig bleiben.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Unsere Flaschen haben verschiedene Farben.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:lesezeit","argument": "Wir sollten eine kurze stille Lesezeit einführen, weil alle gleichzeitig lesen und niemand dazwischen spricht. Zehn stille Minuten lang konnte Maja einem Kapitel bis zum Ende folgen.","optionen": [{"text": "Einige Kinder brauchen beim Lesen einzelner Wörter Unterstützung.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Beim stillen Lesen unterbricht uns kein Gespräch.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Beim Lesen liegen Bücher auf den Tischen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:partnerwahl","argument": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen, weil wir auch mit Kindern außerhalb des Freundeskreises üben. Toni und Esma wurden zum ersten Mal als Paar ausgelost und lösten die Aufgabe zusammen.","optionen": [{"text": "Ein zugelostes Paar könnte bei einer Aufgabe gar nicht weiterkommen.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Durch das Los arbeiten wir auch mit Kindern, die wir seltener wählen.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Bei einer Partneraufgabe arbeiten zwei Kinder zusammen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:ordnung","argument": "Wir sollten gemeinsam benutztes Material fest einsortieren, weil jeder den gleichen Platz für Schere und Kleber kennt. Zoe griff ins beschriftete Fach und fand sofort eine freie Schere.","optionen": [{"text": "Beim schnellen Aufräumen könnte Material im falschen Fach landen.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Scheren und Kleber sind Bastelmaterial.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:spielregeln","argument": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären, weil wir schon vor dem Spiel wissen, welche Regeln gelten. Als der Ball die Linie berührte, kannten beide Teams die vereinbarte Regel.","optionen": [{"text": "Bis wir uns geeinigt haben, bleibt weniger Zeit zum Spielen.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Beim Turnier spielen mehrere Teams.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:radstaender","argument": "Wir sollten Fahrräder an festen Plätzen abstellen, weil kein Rad mitten im Weg vor der Eingangstür steht. Als alle Räder im Ständer standen, kam eine Kindergruppe durch die Tür.","optionen": [{"text": "Die vorhandenen Ständer reichen nicht für alle Fahrräder aus.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die Fahrradständer stehen neben der Schule.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:tauschregal","argument": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen, weil andere Kinder noch verwendbare Sachen weiterbenutzen können. Eine noch volle Packung Buntstifte wurde von einem anderen Kind genutzt.","optionen": [{"text": "Im Regal könnten kaputte oder unbrauchbare Sachen landen.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Im Tauschregal liegen Schulsachen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]},
    {"id": "GEGEN_BELEGT:lernpause","argument": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen, weil wir uns nach etwas Bewegung wieder besser konzentrieren können. Nach dem Strecken konnte Luis der nächsten Erklärung wieder folgen.","optionen": [{"text": "Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe.","ok": true,"info": "Das ist eine Schwierigkeit, die gegen den Vorschlag spricht.","warum": [{"text": "Der Satz nennt ein Problem, das bei dem Vorschlag entstehen kann.","ok": true},{"text": "Der Satz erklärt, warum der Vorschlag hilft.","ok": false},{"text": "Der Satz beschreibt nur, wo etwas steht.","ok": false}]},{"text": "Nach etwas Bewegung fällt es uns leichter, wieder aufzupassen.","ok": false,"info": "Das ist ein Grund für den Vorschlag, kein Gegenargument."},{"text": "Die Bewegungspause liegt zwischen zwei Arbeitsphasen.","ok": false,"info": "Das beschreibt nur das Thema und nennt keinen Nachteil."}]}
