    {"id": "INSELRAT_ABWAEGEN:partnerwahl","meinung": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen.","einwaende": [{"id": "INSELRAT_ABWAEGEN_E:partnerwahl","wer": "Amara und Grimbart","datei": "zwerg-10-amara","einwand": "Ein zugelostes Paar könnte bei einer Aufgabe gar nicht weiterkommen. Schnelle Kinder könnten sofort antworten, bevor ihr Partner nachgedacht hat.","optionen": [{"text": "Bei bleibenden Problemen sind Hilfe und ein Partnerwechsel erlaubt. Vor dem Austausch bekommt jedes Kind eine kurze eigene Denkzeit.","ok": true,"info": "Die Antwort geht auf beide Sorgen ein.","warum": [{"text": "Für beide Sorgen wird eine Lösung vorgeschlagen.","ok": true},{"text": "Nur für die erste Sorge wird eine Lösung vorgeschlagen.","ok": false},{"text": "Nur für die zweite Sorge wird eine Lösung vorgeschlagen.","ok": false}]},{"text": "Bei bleibenden Problemen sind Hilfe und ein Partnerwechsel erlaubt. Wir sammeln nach der Partnerarbeit die gemeinsamen Ergebnisse.","ok": false,"info": "Die zweite Sorge bleibt offen: Schnelle Kinder könnten sofort antworten, bevor ihr Partner nachgedacht hat."},{"text": "Jedes Paar schreibt am Ende seinen Lösungsweg auf. Vor dem Austausch bekommt jedes Kind eine kurze eigene Denkzeit.","ok": false,"info": "Die erste Sorge bleibt offen: Ein zugelostes Paar könnte bei einer Aufgabe gar nicht weiterkommen."}]}]},
    {"id": "INSELRAT_ABWAEGEN:ordnung","meinung": "Wir sollten gemeinsam benutztes Material fest einsortieren.","einwaende": [{"id": "INSELRAT_ABWAEGEN_E:ordnung","wer": "Amara und Grimbart","datei": "zwerg-10-amara","einwand": "Beim schnellen Aufräumen könnte Material im falschen Fach landen. Die beschrifteten Materialfächer könnten für kleine Kinder zu hoch sein.","optionen": [{"text": "Wir zeigen auf jedem Fach den Namen und den Umriss der passenden Gegenstände. Häufig gebrauchte Dinge legen wir in die gut erreichbaren Fächer.","ok": true,"info": "Die Antwort geht auf beide Sorgen ein.","warum": [{"text": "Für beide Sorgen wird eine Lösung vorgeschlagen.","ok": true},{"text": "Nur für die erste Sorge wird eine Lösung vorgeschlagen.","ok": false},{"text": "Nur für die zweite Sorge wird eine Lösung vorgeschlagen.","ok": false}]},{"text": "Wir zeigen auf jedem Fach den Namen und den Umriss der passenden Gegenstände. Wir halten in einer Liste fest, welches Material nachgekauft wird.","ok": false,"info": "Die zweite Sorge bleibt offen: Die beschrifteten Materialfächer könnten für kleine Kinder zu hoch sein."},{"text": "Wir kontrollieren nach dem Basteln, ob jede Schere zurück ist. Häufig gebrauchte Dinge legen wir in die gut erreichbaren Fächer.","ok": false,"info": "Die erste Sorge bleibt offen: Beim schnellen Aufräumen könnte Material im falschen Fach landen."}]}]},
    {"id": "INSELRAT_ABWAEGEN:spielregeln","meinung": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären.","einwaende": [{"id": "INSELRAT_ABWAEGEN_E:spielregeln","wer": "Amara und Grimbart","datei": "zwerg-10-amara","einwand": "Bis wir uns geeinigt haben, bleibt weniger Zeit zum Spielen. Beim Turnier könnten sich beide Mannschaften an verschiedene Absprachen erinnern.","optionen": [{"text": "Wir klären nur strittige Regeln vor dem ersten Turnierspiel. Wir halten die geklärten Regeln auf einer gemeinsamen Karte fest.","ok": true,"info": "Die Antwort geht auf beide Sorgen ein.","warum": [{"text": "Für beide Sorgen wird eine Lösung vorgeschlagen.","ok": true},{"text": "Nur für die erste Sorge wird eine Lösung vorgeschlagen.","ok": false},{"text": "Nur für die zweite Sorge wird eine Lösung vorgeschlagen.","ok": false}]},{"text": "Wir klären nur strittige Regeln vor dem ersten Turnierspiel. Wir teilen die vorhandene Spielzeit gleich auf die Teams auf.","ok": false,"info": "Die zweite Sorge bleibt offen: Beim Turnier könnten sich beide Mannschaften an verschiedene Absprachen erinnern."},{"text": "Wir lassen vor dem Turnier die Mannschaften gleich stark bilden. Wir halten die geklärten Regeln auf einer gemeinsamen Karte fest.","ok": false,"info": "Die erste Sorge bleibt offen: Bis wir uns geeinigt haben, bleibt weniger Zeit zum Spielen."}]}]},
    {"id": "INSELRAT_ABWAEGEN:radstaender","meinung": "Wir sollten Fahrräder an festen Plätzen abstellen.","einwaende": [{"id": "INSELRAT_ABWAEGEN_E:radstaender","wer": "Amara und Grimbart","datei": "zwerg-10-amara","einwand": "Die vorhandenen Ständer reichen nicht für alle Fahrräder aus. Ein Fahrrad könnte auch im Ständer einen schmalen Durchgang versperren.","optionen": [{"text": "Wir markieren zusätzliche Plätze seitlich neben dem Eingang. Wir markieren neben den Rädern einen breiten Durchgang.","ok": true,"info": "Die Antwort geht auf beide Sorgen ein.","warum": [{"text": "Für beide Sorgen wird eine Lösung vorgeschlagen.","ok": true},{"text": "Nur für die erste Sorge wird eine Lösung vorgeschlagen.","ok": false},{"text": "Nur für die zweite Sorge wird eine Lösung vorgeschlagen.","ok": false}]},{"text": "Wir markieren zusätzliche Plätze seitlich neben dem Eingang. Wir regeln, dass alle Räder auf dem Schulgelände geschoben werden.","ok": false,"info": "Die zweite Sorge bleibt offen: Ein Fahrrad könnte auch im Ständer einen schmalen Durchgang versperren."},{"text": "Wir zeigen im Schulwegplan den Standort der Fahrradständer. Wir markieren neben den Rädern einen breiten Durchgang.","ok": false,"info": "Die erste Sorge bleibt offen: Die vorhandenen Ständer reichen nicht für alle Fahrräder aus."}]}]},
    {"id": "INSELRAT_ABWAEGEN:tauschregal","meinung": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen.","einwaende": [{"id": "INSELRAT_ABWAEGEN_E:tauschregal","wer": "Amara und Grimbart","datei": "zwerg-10-amara","einwand": "Im Regal könnten kaputte oder unbrauchbare Sachen landen. Einige Kinder könnten gleich alle brauchbaren Sachen aus dem Regal nehmen.","optionen": [{"text": "Der Dienst prüft, ob die Sachen noch benutzbar sind. Jedes Kind darf zuerst nur eine Sache nehmen.","ok": true,"info": "Die Antwort geht auf beide Sorgen ein.","warum": [{"text": "Für beide Sorgen wird eine Lösung vorgeschlagen.","ok": true},{"text": "Nur für die erste Sorge wird eine Lösung vorgeschlagen.","ok": false},{"text": "Nur für die zweite Sorge wird eine Lösung vorgeschlagen.","ok": false}]},{"text": "Der Dienst prüft, ob die Sachen noch benutzbar sind. Wir schreiben auf ein Schild, dass die Sachen kostenlos sind.","ok": false,"info": "Die zweite Sorge bleibt offen: Einige Kinder könnten gleich alle brauchbaren Sachen aus dem Regal nehmen."},{"text": "Wir ordnen Hefte und Stifte in getrennte Fächer des Regals. Jedes Kind darf zuerst nur eine Sache nehmen.","ok": false,"info": "Die erste Sorge bleibt offen: Im Regal könnten kaputte oder unbrauchbare Sachen landen."}]}]},
    {"id": "INSELRAT_ABWAEGEN:lernpause","meinung": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen.","einwaende": [{"id": "INSELRAT_ABWAEGEN_E:lernpause","wer": "Amara und Grimbart","datei": "zwerg-10-amara","einwand": "Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe. Bei Bewegung im Raum könnten Kinder an Tischkanten stoßen.","optionen": [{"text": "Ein klares Endzeichen zeigt, wann wir wieder an der Aufgabe arbeiten. Wir wählen sichere Bewegungen mit genug Platz am eigenen Sitz.","ok": true,"info": "Die Antwort geht auf beide Sorgen ein.","warum": [{"text": "Für beide Sorgen wird eine Lösung vorgeschlagen.","ok": true},{"text": "Nur für die erste Sorge wird eine Lösung vorgeschlagen.","ok": false},{"text": "Nur für die zweite Sorge wird eine Lösung vorgeschlagen.","ok": false}]},{"text": "Ein klares Endzeichen zeigt, wann wir wieder an der Aufgabe arbeiten. Wir besprechen, bei welchen Aufgaben eine Pause nötig wird.","ok": false,"info": "Die zweite Sorge bleibt offen: Bei Bewegung im Raum könnten Kinder an Tischkanten stoßen."},{"text": "Wir lassen die Kinder kurze Übungen für die Pause vorschlagen. Wir wählen sichere Bewegungen mit genug Platz am eigenen Sitz.","ok": false,"info": "Die erste Sorge bleibt offen: Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe."}]}]}
